/*
 * A091734  Permutation of primes generated by array shown below.
 * https://oeis.org/A091734
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the nth term of the permutation of primes * obtained by
 *            reading the following 3×∞ array in antidiagonal order: * * Row
 *            1: 2, 11, 17, 31, 41, 59, 67, 83, 97, … * Row 2: 3, 7, 19, 29,
 *            43, 53, 71, 79,101, … * Row 3: 5, 13, 23, 37, 47, 61, 73,
 *            89,103, … * * The first three terms are hard‑code...
 * Range:     u8 n <= 42, u16 n <= 42, u32 n <= 42, u64 n <= 42, u128 n <= 42,
 *            big any n
 * Helpers:   n_to_row_col, prime_index_by_row_col
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include "../utils/n_to_row_col.h"
#include "../utils/prime_index_by_row_col.h"

static const idx_t LIMIT_PRIME_SIEVE = 200000;    /* enough for the required range */
static uint32_t *prime_list   = NULL;
static size_t   prime_cnt     = 0;
static bool     primes_ready  = false;

/* Simple Eratosthenes sieve – executed once. */
static void init_primes(void)
{
    unsigned char *is_prime = NULL;
    if (prime_list) return;                   /* already done */

    is_prime = (unsigned char*)malloc((LIMIT_PRIME_SIEVE + 1) * sizeof(unsigned char));
    if (!is_prime) exit(1);
    memset(is_prime, 1, LIMIT_PRIME_SIEVE + 1);
    is_prime[0] = 0;  is_prime[1] = 0;

    for (idx_t i = 2; i * i <= LIMIT_PRIME_SIEVE; ++i) {
        if (is_prime[i]) {
            for (idx_t j = i * i; j <= LIMIT_PRIME_SIEVE; j += i)
                is_prime[j] = 0;
        }
    }

    /* Count primes to allocate the list. */
    size_t est = 20000;                       /* rough estimate */
    prime_list = (uint32_t*)malloc(est * sizeof(uint32_t));
    if (!prime_list) exit(1);

    for (idx_t i = 2; i <= LIMIT_PRIME_SIEVE; ++i) {
        if (is_prime[i]) {
            if (prime_cnt == est) {           /* grow if needed */
                est <<= 1;
                prime_list = (uint32_t*)realloc(prime_list, est * sizeof(uint32_t));
                if (!prime_list) exit(1);
            }
            prime_list[prime_cnt++] = (uint32_t)i;
        }
    }
    free(is_prime);
}

seq_t a(idx_t n)
{
    if (!primes_ready) { init_primes(); primes_ready = true; }
    if (n < 1) return (seq_t)0;

    /* Hard‑code the first three terms – otherwise modular arithmetic
     * on n < 4 would give negative values. */
    if (n == 1) return (seq_t)2;   /* row 1, col 1 */
    if (n == 2) return (seq_t)3;   /* row 2, col 1 */
    if (n == 3) return (seq_t)11;  /* row 1, col 2 */

    idx_t row, col;
    n_to_row_col(n, &row, &col);

    idx_t idx = prime_index_by_row_col(row, col); /* 1‑based index in the prime list */

    if ((size_t)idx > prime_cnt) return (seq_t)0; /* safety guard */

    return (seq_t)prime_list[idx - 1];
}
